void burst() {
  PresenceBurst round;
  assert(round.attempts() == 1);
  assert(!round.due(4999));
  assert(round.due(5000)); round.advanced(5000);
  assert(!round.due(11999));
  assert(round.due(12000)); round.advanced(12000);
  assert(!round.due(21999));
  assert(round.due(22000)); round.advanced(22000);
  assert(!round.fallbackDue(27000));
  for (uint32_t offset : {30000U, 40000U, 50000U, 60000U}) {
    assert(!round.due(offset - 1));
    assert(round.due(offset));
    round.advanced(offset);
    assert(!round.fallbackDue(offset));
  }
  assert(round.attempts() == 8);
  assert(!round.due(70000));
  assert(!round.fallbackDue(64999));
  assert(round.fallbackDue(65000));
  round.reset();
  assert(round.due(10000)); round.advanced(10000);
  assert(!round.due(12000)); // A delayed loop does not send missed retries back-to-back.
  assert(round.due(15000));
  assert(PresenceBurst::TIMEOUT_MS == 75000);
  assert(PresenceBurst::RECEIVE_WINDOW_MS > PresenceBurst::TIMEOUT_MS);
}

void logRing() {
  LogRing<unsigned, 96> log;
  assert(log.size() == 0 && !log.newest(0));
  for (unsigned i = 0; i < 200; ++i) log.append(i);
  assert(log.size() == 96 && log.generation() == 200);
  assert(*log.newest(0) == 199 && *log.newest(95) == 104);
  assert(!log.newest(96));
  unsigned read = 0;
  for (unsigned offset = 0; offset < log.size(); offset += 24) {
    for (unsigned page = 0; page < 24 && offset + page < log.size(); ++page) {
      assert(*log.newest(offset + page) == 199 - read++);
    }
  }
  assert(read == 96);
}

void packets() {
  const uint32_t target = 0xC0A8B22B, local = 0xC0A8B220;
  const uint16_t token = 123, port = 49999;
  uint8_t question[64];
  const size_t questionSize = Probe::mdnsQuestion(question, sizeof(question), target, token);
  assert(questionSize > 12 && questionSize < sizeof(question));
  assert(!Probe::mdnsQuestion(question, 12, target, token));
  size_t nameOffset = 12;
  char name[128];
  assert(Probe::dnsName(question, questionSize, nameOffset, name, sizeof(name)));
  assert(!strcmp(name, "43.178.168.192.in-addr.arpa"));
  uint8_t reply[128] = {0};
  memcpy(reply, question, questionSize);
  reply[2] = 0x80;
  Probe::write16(reply + 6, 1);
  size_t size = questionSize;
  reply[size++] = 0xC0; reply[size++] = 12;
  Probe::write16(reply + size, 12); size += 2;
  Probe::write16(reply + size, 1); size += 2;
  reply[size++] = 0; reply[size++] = 0; reply[size++] = 0; reply[size++] = 120;
  Probe::write16(reply + size, 3); size += 2;
  reply[size++] = 1; reply[size++] = 'x'; reply[size++] = 0;
  assert(Probe::mdnsReply(reply, size, target, token));
  assert(!Probe::mdnsReply(reply, size, target, token + 1));
  assert(!Probe::mdnsReply(reply, size, target + 1, token));
  for (size_t truncated = 0; truncated < size; ++truncated) assert(!Probe::mdnsReply(reply, truncated, target, token));
  uint8_t cycle[14] = {0}; cycle[12] = 0xC0; cycle[13] = 12;
  nameOffset = 12;
  assert(!Probe::dnsName(cycle, sizeof(cycle), nameOffset, name, sizeof(name)));
  const uint8_t ownMac[6] = {2, 3, 4, 5, 6, 7}, phoneMac[6] = {8, 9, 10, 11, 12, 13};
  uint8_t arp[42] = {0};
  memcpy(arp, ownMac, 6); memcpy(arp + 6, phoneMac, 6); memcpy(arp + 22, phoneMac, 6); memcpy(arp + 32, ownMac, 6);
  Probe::write16(arp + 12, 0x0806); Probe::write16(arp + 14, 1); Probe::write16(arp + 16, 0x0800);
  arp[18] = 6; arp[19] = 4; Probe::write16(arp + 20, 2);
  for (unsigned i = 0; i < 4; ++i) { arp[28 + i] = target >> ((3 - i) * 8); arp[38 + i] = local >> ((3 - i) * 8); }
  assert(Probe::arpReply(arp, sizeof(arp), target, local, ownMac));
  assert(!Probe::arpReply(arp, sizeof(arp), target + 1, local, ownMac));
  arp[21] = 1; assert(!Probe::arpReply(arp, sizeof(arp), target, local, ownMac)); arp[21] = 2;
  for (size_t truncated = 0; truncated < sizeof(arp); ++truncated) assert(!Probe::arpReply(arp, truncated, target, local, ownMac));
  uint8_t icmp[80] = {0};
  icmp[0] = 0x45; icmp[9] = 1; icmp[20] = 3; icmp[21] = 3; icmp[28] = 0x45; icmp[37] = 17;
  for (unsigned i = 0; i < 4; ++i) {
    icmp[12 + i] = icmp[44 + i] = target >> ((3 - i) * 8);
    icmp[16 + i] = icmp[40 + i] = local >> ((3 - i) * 8);
  }
  Probe::write16(icmp + 48, port); Probe::write16(icmp + 50, 5353); Probe::write16(icmp + 52, 12); Probe::write16(icmp + 56, token);
  assert(Probe::portUnreachable(icmp, 58, target, local, port, token));
  assert(!Probe::portUnreachable(icmp, 58, target, local, port + 1, token));
  assert(!Probe::portUnreachable(icmp, 58, target, local, port, token + 1));
  assert(!Probe::portUnreachable(icmp, 58, target + 1, local, port, token));
  for (size_t truncated = 0; truncated < 56; ++truncated) assert(!Probe::portUnreachable(icmp, truncated, target, local, port, token));
  uint32_t random = 5;
  uint8_t data[512];
  for (unsigned sample = 0; sample < 10000; ++sample) {
    for (uint8_t& value : data) { random = random * 1664525U + 1013904223U; value = random >> 24; }
    const size_t length = random % sizeof(data);
    Probe::mdnsReply(data, length, target, token);
    Probe::arpReply(data, length, target, local, ownMac);
    Probe::portUnreachable(data, length, target, local, port, token);
  }
}

void atomics() {
  Atomic<uint8_t> bits {0};
  assert(bits.fetch_or(1) == 0);
  assert(bits.fetch_or(4) == 1);
  assert(bits.load() == 5);
  assert(bits.exchange(0) == 5);
  assert(bits++ == 0);
  assert(--bits == 0);
  Atomic<bool> flag {true};
  assert(flag.exchange(false));
  assert(!flag.load());
  Atomic<uint32_t> revision {1};
  revision = UINT32_MAX;
  assert(revision.load() == UINT32_MAX);
}

